async function unlockWithPin(){if(!session?.access_token){setShowRegisterSetup(true);setError('Authorize this register once to enable PIN verification. Your PIN entry will be retained.');return}setBusy(true);setError('');try{let currentToken=session.access_token;if(session.expires_at&&Date.now()/1000>=session.expires_at-60)currentToken=await refreshTerminalSession();let ok;try{ok=await request('/rest/v1/rpc/pos_verify_my_pin',{method:'POST',token:currentToken,body:{candidate:pinInput}})}catch(e){if(!/JWT expired|invalid jwt|401|token expired/i.test(e.message))throw e;currentToken=await refreshTerminalSession();ok=await request('/rest/v1/rpc/pos_verify_my_pin',{method:'POST',token:currentToken,body:{candidate:pinInput}})}if(ok!==true)throw Error('PIN verification failed. Check the assigned PIN or contact a manager.');setUnlocked(true);setPinInput('');setTab('POS')}catch(e){if(/JWT expired|invalid jwt|401|token expired|Authentication required|Inactive staff account/i.test(e.message)){setShowRegisterSetup(true);setError('Saved register authorization expired or is invalid. Sign in here again to renew it.')}else setError(e.message);setPinInput('')}finally{setBusy(false)}}
async function sendPasswordReset(){if(!email.trim()){setError('Enter your account email first, then select Forgot password.');return}setBusy(true);setError('');try{await request('/auth/v1/recover?redirect_to='+encodeURIComponent(window.location.origin+'/backoffice'),{method:'POST',body:{email:email.trim()}});setError('If this email is registered, a password reset link will arrive shortly. Check spam if needed.')}catch(e){setError('Unable to send reset email: '+e.message)}finally{setBusy(false)}}
async function login(e){e.preventDefault();setBusy(true);setError('');try{const s=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email,password}});if(window.location.pathname.startsWith('/backoffice')||saveRegisterAuthorization)localStorage.setItem(STORE,JSON.stringify(s));else sessionStorage.setItem(STORE,JSON.stringify(s));setSession(s);setUnlocked(window.location.pathname.startsWith('/backoffice'));setShowRegisterSetup(false);setLoginMode('admin');setTab(window.location.pathname.startsWith('/backoffice')?'Management':'POS');setPassword('');setPinInput('')}catch(e){setError(e.message)}finally{setBusy(false)}}
useEffect(()=>{if(!staff?.restaurant_id||!token||!['owner','manager'].includes(staff.role))return;let active=true;api('pos_tip_policies?select=id,name,method,bartender_percent,support_percent,approval_required,status,max_tip_percent,max_tip_cents,show_tip_limit,suggested_tip_percents&restaurant_id=eq.'+encodeURIComponent(staff.restaurant_id)+'&order=updated_at.desc&limit=1',{token}).then(rows=>{if(active&&rows?.length){setTipPolicy(rows[0]);setTipPolicyId(rows[0].id)}}).catch(e=>{if(active)setTipMessage('Unable to load saved tip policy: '+e.message)});return()=>{active=false}},[staff?.restaurant_id,token]);
useEffect(()=>{if(!staff?.restaurant_id||!token)return;let live=true;api('pos_receipt_branding?select=logo_mono_data_url,logo_enabled&restaurant_id=eq.'+encodeURIComponent(staff.restaurant_id),{token}).then(rows=>{if(live&&rows?.[0]){setReceiptLogo(rows[0].logo_mono_data_url);setReceiptLogoEnabled(rows[0].logo_enabled)}}).catch(()=>{});return()=>{live=false}},[staff?.restaurant_id,token]);
async function uploadReceiptLogo(e){const file=e.target.files?.[0];if(!file)return;setReceiptLogoMessage('');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5000000){setReceiptLogoMessage('Choose a PNG, JPG or WebP image smaller than 5 MB.');return}try{const img=new Image();const src=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=src});const canvas=document.createElement('canvas');canvas.width=384;canvas.height=Math.max(64,Math.min(300,Math.round(img.height*384/img.width)));const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<data.data.length;i+=4){const gray=.299*data.data[i]+.587*data.data[i+1]+.114*data.data[i+2];const v=gray<170?0:255;data.data[i]=v;data.data[i+1]=v;data.data[i+2]=v;data.data[i+3]=255}ctx.putImageData(data,0,0);const output=canvas.toDataURL('image/png');if(output.length>=250000)throw Error('Logo is too detailed for the thermal format. Try a simpler image.');setReceiptLogo(output);setReceiptLogoMessage('Black-and-white logo ready. Select Save Receipt Logo to keep it.')}finally{URL.revokeObjectURL(src)}}catch(err){setReceiptLogoMessage(err.message)}}
async function saveReceiptLogo(){if(!staff?.restaurant_id||!['owner','manager'].includes(staff.role))return;setBusy(true);try{await api('pos_receipt_branding?on_conflict=restaurant_id',{method:'POST',token,prefer:'resolution=merge-duplicates,return=minimal',body:{restaurant_id:staff.restaurant_id,logo_mono_data_url:receiptLogo,logo_enabled:receiptLogoEnabled,updated_by:session.user.id,updated_at:new Date().toISOString()}});setReceiptLogoMessage('Receipt logo saved for this restaurant. Printer integration is not active yet.')}catch(err){setReceiptLogoMessage('Could not save logo: '+err.message)}finally{setBusy(false)}}
async function saveTipPolicy(e){e.preventDefault();if(!staff?.restaurant_id||!['owner','manager'].includes(staff.role))return;setBusy(true);setTipMessage('');try{const body={restaurant_id:staff.restaurant_id,name:tipPolicy.name.trim()||'Default tip policy',method:tipPolicy.method,bartender_percent:Number(tipPolicy.bartender_percent)||0,support_percent:Number(tipPolicy.support_percent)||0,approval_required:tipPolicy.approval_required,max_tip_percent:Number(tipPolicy.max_tip_percent),max_tip_cents:tipPolicy.max_tip_cents==null||tipPolicy.max_tip_cents===''?null:Number(tipPolicy.max_tip_cents),show_tip_limit:tipPolicy.show_tip_limit,suggested_tip_percents:tipPolicy.suggested_tip_percents,status:'draft',updated_at:new Date().toISOString(),updated_by:session.user.id};if(body.bartender_percent+body.support_percent>100)throw Error('Tip-out percentages cannot exceed 100%');const rows=await api('pos_tip_policies'+(tipPolicyId?'?id=eq.'+tipPolicyId:''),{method:tipPolicyId?'PATCH':'POST',token,body,prefer:'return=representation'});if(rows?.[0]?.id)setTipPolicyId(rows[0].id);setTipPolicy(p=>({...p,status:'draft'}));setTipMessage('Draft policy saved for this restaurant. Live distribution is not enabled until payment and allocation processing are implemented.')}catch(e){setTipMessage('Save failed: '+e.message)}finally{setBusy(false)}}
async function loadDrawers(){if(!staff?.restaurant_id||!token)return;try{const id=encodeURIComponent(staff.restaurant_id);const [d,sh]=await Promise.all([api('pos_cash_drawers?select=id,name,active,starting_bank_cents&restaurant_id=eq.'+id+'&active=eq.true&order=name',{token}),api('pos_drawer_shifts?select=id,drawer_id,staff_id,opening_cents,employee_closing_cents,status,opened_at&restaurant_id=eq.'+id+'&status=eq.open',{token})]);setDrawers(d||[]);setDrawerShifts(sh||[]);if(!drawerChoice&&d?.[0])setDrawerChoice(d[0].id)}catch(e){setDrawerMessage('Unable to load drawers: '+e.message)}}
useEffect(()=>{if(staff?.restaurant_id&&token)loadDrawers()},[staff?.restaurant_id,token]);
async function saveDrawerSetup(){if(!['owner','manager'].includes(staff?.role))return;setBusy(true);setDrawerMessage('');try{const cents=Math.round(Number(drawerSetupBank)*100);if(!drawerSetupName.trim()||!Number.isSafeInteger(cents)||cents<0)throw Error('Enter drawer name and a valid starting cash amount');await request('/rest/v1/rpc/pos_manager_set_drawer',{method:'POST',token,body:{p_drawer:drawerSetupId||null,p_name:drawerSetupName.trim(),p_starting_bank_cents:cents,p_active:true}});setDrawerMessage('Drawer settings saved.');setDrawerSetupId('');setDrawerSetupName('');await loadDrawers()}catch(e){setDrawerMessage('Unable to save drawer: '+e.message)}finally{setBusy(false)}}
async function inspectDrawer(shiftId){try{const result=await request('/rest/v1/rpc/pos_drawer_expected',{method:'POST',token,body:{p_shift:shiftId}});setDrawerExpected(p=>({...p,[shiftId]:result}))}catch(e){setDrawerMessage('Could not calculate drawer: '+e.message)}}
async function drawerAction(action,shiftId){setBusy(true);setDrawerMessage('');try{const cents=Math.round(Number(drawerCount)*100);if(!Number.isFinite(cents)||cents<0)throw Error('Enter a valid cash count');if(action==='claim'){if(!['owner','manager'].includes(staff?.role))throw Error('Only managers can assign drawers');if(!drawerEmployee)throw Error('Select an employee');const configured=drawers.find(d=>d.id===drawerChoice);if(configured&&cents!==configured.starting_bank_cents)throw Error('Count differs from configured starting bank ('+money(configured.starting_bank_cents)+'). Manager must resolve the difference before assigning.');await request('/rest/v1/rpc/pos_manager_assign_drawer',{method:'POST',token,body:{p_drawer:drawerChoice,p_staff:drawerEmployee,p_opening_cents:cents}})}else await request('/rest/v1/rpc/pos_manager_close_drawer',{method:'POST',token,body:{p_shift:shiftId,p_closing_cents:cents,p_reason:null}});setDrawerMessage(action==='claim'?'Drawer assigned. Locking the screen does not release it.':'Drawer closed.');await loadDrawers()}catch(e){setDrawerMessage(e.message)}finally{setBusy(false)}}
async function submitDrawerCount(shiftId){setBusy(true);setDrawerMessage('');try{const cents=Math.round(Number(drawerCount)*100);if(!Number.isSafeInteger(cents)||cents<0)throw Error('Enter a valid count');await request('/rest/v1/rpc/pos_employee_submit_drawer_count',{method:'POST',token,body:{p_shift:shiftId,p_count_cents:cents}});setDrawerMessage('Employee closing count submitted. Manager must verify and approve.');await loadDrawers()}catch(e){setDrawerMessage(e.message)}finally{setBusy(false)}}
async function approveDrawerClose(shiftId){setBusy(true);setDrawerMessage('');try{const cents=Math.round(Number(drawerCount)*100);if(!Number.isSafeInteger(cents)||cents<0)throw Error('Enter manager count');const result=await request('/rest/v1/rpc/pos_manager_approve_drawer_close',{method:'POST',token,body:{p_shift:shiftId,p_manager_count_cents:cents,p_reason:drawerCloseReason||null}});setDrawerMessage('Drawer closed. Expected '+money(result.expected_cents)+' · Actual '+money(result.actual_cents)+' · Variance '+money(result.variance_cents));await loadDrawers()}catch(e){setDrawerMessage(e.message)}finally{setBusy(false)}}
async function takeCashPayment(){if(!cashTicket)return;setBusy(true);setCashResult('');try{const cents=Math.round(Number(cashTender)*100);if(!Number.isSafeInteger(cents)||cents<=0)throw Error('Enter cash received');const result=await request('/rest/v1/rpc/pos_take_cash_payment',{method:'POST',token,body:{p_ticket:cashTicket,p_tendered_cents:cents}});setCashResult('Cash sale recorded. Change due: '+money(result.change_cents));setCashTicket('');setCashTender('');await sync();await loadDrawers()}catch(e){setCashResult('Cash sale not completed: '+e.message)}finally{setBusy(false)}}
async function loadShiftCloseout(){setBusy(true);setCloseoutError('');try{const report=await request('/rest/v1/rpc/pos_shift_sales_summary',{method:'POST',token,body:{p_shift_date:closeoutDate,p_staff:closeoutStaff||null}});setCloseoutReport(report)}catch(e){setCloseoutError(e.message)}finally{setBusy(false)}}
async function recordShiftTips(){setBusy(true);setCloseoutError('');try{const a=Math.round(Number(cashTipsInput)*100),b=Math.round(Number(tipoutInput)*100);if(!Number.isSafeInteger(a)||!Number.isSafeInteger(b)||a<0||b<0)throw Error('Enter valid tip amounts');await request('/rest/v1/rpc/pos_manager_record_shift_tips',{method:'POST',token,body:{p_staff:closeoutStaff||staff.id,p_shift_date:closeoutDate,p_cash_tips_cents:a,p_tipout_paid_cents:b,p_note:null}});setCloseoutError('Manager tip declaration saved. Settlement remains pending.');await loadShiftCloseout()}catch(e){setCloseoutError(e.message)}finally{setBusy(false)}}
async function certifyNightCash(){setBusy(true);setCashCertStatus('');try{const result=await request('/rest/v1/rpc/pos_manager_certify_night_cash',{method:'POST',token,body:{p_date:closeoutDate}});setCashCertStatus('Night cash count certified by manager. Full financial close is still pending.');await loadNightReport()}catch(e){setCashCertStatus(e.message)}finally{setBusy(false)}}
async function reconcileServerCash(){setBusy(true);setCloseoutError('');try{const cents=Math.round(Number(serverCashCount)*100);if(!Number.isSafeInteger(cents)||cents<0)throw Error('Enter valid cash received');const result=await request('/rest/v1/rpc/pos_manager_reconcile_server',{method:'POST',token,body:{p_staff:closeoutStaff||staff.id,p_date:closeoutDate,p_received_cents:cents,p_reason:serverVarianceReason||null}});setCloseoutError('Server cash turn-in reconciled. Variance: '+money(result.variance_cents));await loadNightReport()}catch(e){setCloseoutError(e.message)}finally{setBusy(false)}}
