function printCloseout(kind){if(!['owner','manager'].includes(staff?.role))return;const data=kind==='night'?nightReport:closeoutReport;if(!data)return;const w=window.open('','_blank','width=800,height=900');if(!w){setNightError('Allow pop-ups to print');return}const h=w.document.createElement('h2');h.textContent=kind==='night'?'TAP3 MANAGER NIGHT CLOSEOUT':'TAP3 EMPLOYEE SHIFT CLOSEOUT';w.document.body.appendChild(h);const p=w.document.createElement('pre');p.style.cssText='white-space:pre-wrap;font:13px monospace';p.textContent=JSON.stringify(data,null,2);w.document.body.appendChild(p);const note=w.document.createElement('p');note.textContent='PROVISIONAL MANAGER REPORT: Card sales, card tips, refunds and tip allocation not connected. Not valid for final settlement.';w.document.body.appendChild(note);w.print()}
async function submitCashTipClaim(){setBusy(true);setClaimStatus('');try{const cents=Math.round(Number(claimTip)*100);if(!claimReceipt||!Number.isSafeInteger(cents)||cents<0)throw Error('Choose a completed receipt and enter the cash tip');await request('/rest/v1/rpc/pos_claim_receipt_cash_tip',{method:'POST',token,body:{p_ticket:claimReceipt,p_cash_tip_cents:cents}});setClaimStatus('Cash tip claim submitted for manager review. Clock out in Restaurant Workforce.');setClaimReceipt('');setClaimTip('')}catch(e){setClaimStatus(e.message)}finally{setBusy(false)}}
